    {
      "accion": "veredicto",
      "hipotesis": "H4",
      "veredicto": "sostenida",
      "razon": "En la segunda quincena, 14 de las 18 disputas son de RapidEnvio en la región Norte con zona con atrasos, y las 14 tienen causa_operativa. Las demás combinaciones de transportista y región tienen solo 1 o 2 disputas cada una y sin causa operativa.",
      "evidencia": ["E4"]
    },
    {
      "accion": "consultar",
      "hipotesis": "H1",
      "sql": "WITH d AS (\n  SELECT * FROM canonico.disputas\n  WHERE abierta_en >= TIMESTAMP '2026-09-16 00:00:00'\n    AND abierta_en <= TIMESTAMP '2026-09-30 23:59:59'\n)\nSELECT razon_decision, count(*) AS disputas\nFROM d\nGROUP BY razon_decision\nORDER BY disputas DESC;"
    }
  ]
